async function savePokemonEntryWithConflictRetry(pokemonId,reapply){
  let result=await saveNow();
  if(result?.ok)return result;
  if(result?.status==="conflict"&&typeof reapply==="function"){
    try{
      const fresh=entry(pokemonId);
      if(reapply(fresh)!==false)result=await saveNow();
    }catch(err){
      console.error("Could not reapply Pokémon change after save conflict",err);
      result={ok:false,status:"error"};
    }
  }
  if(!result?.ok&&!publicMode&&user&&!isAdminTestMode()){
    try{await loadSave()}catch(err){console.warn("Could not reload protected Pokémon cloud save",err)}
  }
  return result||{ok:false,status:"error"};
}

